/**
 * Canonical, Open Graph, and Twitter tags for static public pages.
 * Requires js/hub-seo-static-config.js (generated by npm run build-seo).
 */
(function () {
  function detectPage() {
    var script = document.currentScript;
    if (script) {
      var page = script.getAttribute('data-page');
      if (page) return page;
    }
    var navScript = document.querySelector('script[data-page][src*="site-nav"]');
    if (navScript) return navScript.getAttribute('data-page') || '';

    var path = (window.location.pathname || '').toLowerCase();
    if (/\/events\/(?:index\.html)?$/.test(path) || /\/events\/?$/.test(path)) return 'events';
    if (/\/opportunities\//.test(path)) return 'opportunities';
    if (/\/guides\.html$/.test(path)) return 'guides';
    if (/\/guides\/list-an-event\.html$/.test(path)) return 'guide-list-an-event';
    if (/\/guides\/list-a-conference-or-exhibition\.html$/.test(path)) return 'guide-list-a-conference-or-exhibition';
    if (/\/guides\/list-a-business-opportunity\.html$/.test(path)) return 'guide-list-a-business-opportunity';
    if (/\/guides\/invite-your-team\.html$/.test(path)) return 'guide-invite-your-team';
    if (/\/faq\.html$/.test(path)) return 'faq';
    if (/\/help\/organiser-payouts(?:\.html)?\/?$/.test(path)) return 'help-organiser-payouts';
    if (/\/help\/pricing-fees(?:\.html)?\/?$/.test(path)) return 'help-pricing-fees';
    if (/\/contact\.html$/.test(path)) return 'contact';
    if (/\/about\.html$/.test(path)) return 'about';
    if (/\/for-organisers\.html$/.test(path)) return 'for-organisers';
    if (/\/advertising(?:\.html)?\/?$/.test(path)) return 'advertising';
    if (/\/legal-policies\.html$/.test(path)) return 'legal';
    if (/index\.html$/.test(path) || /\/$/.test(path)) return 'home';
    return '';
  }

  function upsertMeta(attr, key, value) {
    if (!value) return;
    var selector = attr === 'name' ? 'meta[name="' + key + '"]' : 'meta[property="' + key + '"]';
    var el = document.querySelector(selector);
    if (!el) {
      el = document.createElement('meta');
      el.setAttribute(attr, key);
      document.head.appendChild(el);
    }
    el.setAttribute('content', value);
  }

  function upsertCanonical(href) {
    if (!href) return;
    var el = document.querySelector('link[rel="canonical"]');
    if (!el) {
      el = document.createElement('link');
      el.setAttribute('rel', 'canonical');
      document.head.appendChild(el);
    }
    el.setAttribute('href', href);
  }

  function absoluteUrl(path) {
    var origin = (window.location.origin || '').replace(/\/$/, '');
    if (!path) return origin + '/';
    if (/^https?:\/\//i.test(path)) return path;
    return origin + (path.startsWith('/') ? path : '/' + path);
  }

  var page = detectPage();
  var cfg = window.HUB_SEO_STATIC && page ? window.HUB_SEO_STATIC[page] : null;
  if (!cfg) return;

  var canonical = absoluteUrl(cfg.path);
  var image = absoluteUrl(cfg.image || '/assets/logo.png');

  if (cfg.title) document.title = cfg.title;
  upsertMeta('name', 'description', cfg.description);
  upsertCanonical(canonical);

  upsertMeta('property', 'og:type', cfg.ogType || 'website');
  upsertMeta('property', 'og:site_name', 'The Networker Hub');
  upsertMeta('property', 'og:title', cfg.title);
  upsertMeta('property', 'og:description', cfg.description);
  upsertMeta('property', 'og:url', canonical);
  upsertMeta('property', 'og:image', image);
  upsertMeta('name', 'twitter:card', image ? 'summary_large_image' : 'summary');
  upsertMeta('name', 'twitter:title', cfg.title);
  upsertMeta('name', 'twitter:description', cfg.description);
  upsertMeta('name', 'twitter:image', image);
})();
